// tree-sitter grammar for qkt strategy files. Generated by `qkt editor grammar --format tree-sitter`;
// edit src/main/kotlin/com/qkt/editor/ and regenerate rather than editing this file.

// Case-insensitive like the lexer: 'BUY' matches buy, Buy and BUY.
const ci = (word) =>
  new RegExp(word.split('').map((c) => (/[a-z]/i.test(c) ? '[' + c.toLowerCase() + c.toUpperCase() + ']' : c)).join(''));
const words = (...ws) => choice(...ws.map(ci));

module.exports = grammar({
  name: 'qkt',
  extras: ($) => [/\s/, $.comment],
  word: ($) => $.identifier,
  rules: {
    source_file: ($) => repeat($._item),
    _item: ($) =>
      choice(
        $.keyword_section,
        $.keyword_flow,
        $.keyword_action,
        $.keyword_order,
        $.keyword_sizing,
        $.keyword_bracket,
        $.keyword_stacking,
        $.keyword_portfolio,
        $.keyword_session,
        $.keyword_hook,
        $.keyword_state,
        $.keyword_operator_word,
        $.keyword_aggregate,
        $.keyword_literal,
        $.call,
        $.member,
        $.broker_symbol,
        $.duration,
        $.number,
        $.string,
        $.operator,
        $.punctuation,
        $.identifier,
      ),
    keyword_section: (_) => words('BASKET', 'DEFAULTS', 'IMPORT', 'LET', 'PARAM', 'PORTFOLIO', 'REGIMES', 'RULES', 'SCHEDULE', 'SEQUENCE', 'SERIES', 'STRATEGY', 'SYMBOLS', 'SYNCHRONIZE', 'VERSION'),
    keyword_flow: (_) => words('CASE', 'DO', 'EACH', 'ELSE', 'END', 'EVERY', 'FOR', 'IN', 'SINCE', 'THEN', 'WHEN'),
    keyword_action: (_) => words('BUY', 'CANCEL', 'CANCEL_ALL', 'CLOSE', 'CLOSE_ALL', 'DEBUG', 'ERROR', 'FLATTEN', 'LOG', 'RESIZE', 'SELL', 'WARN'),
    keyword_order: (_) => words('AT', 'BY', 'DAY', 'FLOOR', 'FOK', 'GTC', 'GTD', 'IOC', 'LIMIT', 'MARKET', 'ORDER_TYPE', 'PCT', 'STEP', 'STOP', 'STOP_LOSS', 'TAKE_PROFIT', 'TIF', 'TIGHTEN', 'TO', 'TRAILING', 'UNTIL'),
    keyword_sizing: (_) => words('BALANCE', 'EQUITY', 'MIN_STEP', 'OF', 'RISK', 'SIZING', 'USD'),
    keyword_bracket: (_) => words('AGAINST', 'ARM', 'BRACKET', 'CLOSE_BEYOND', 'CONFIRM', 'ENTER', 'EXPIRE', 'FROM', 'LATCH', 'LOSS', 'OCO', 'OCO_ENTRY', 'OFFSET', 'ON', 'PROFIT', 'RETEST_HOLD', 'RETRACE', 'RR', 'TAKE', 'TIME_IN_BREACH', 'WITH'),
    keyword_stacking: (_) => words('AFTER', 'MAE', 'MFE', 'RECOVER', 'SPACING', 'STACK', 'STACK_AT', 'STAGE', 'TIMES', 'WITHIN'),
    keyword_portfolio: (_) => words('ALLOCATE', 'AS', 'CAPITAL', 'CASH', 'DEFAULT', 'EQUAL_WEIGHT', 'HOLD', 'METHOD', 'NAME', 'OVERRIDE', 'REBALANCE', 'RUN', 'STATE', 'WEIGHT'),
    keyword_session: (_) => words('BARS', 'BROKER', 'CHICAGO', 'HOUR', 'LONDON', 'NY', 'SYDNEY', 'TOKYO', 'UTC', 'WARMUP', 'WEEKDAY'),
    keyword_hook: (_) => words('ON_CLOSE', 'ON_FILL', 'ON_STOP', 'ON_TP'),
    keyword_state: (_) => words('ACCOUNT', 'COOLDOWN', 'ENTRY_QTY', 'EXIT', 'NOW', 'OPEN_ORDERS', 'POSITION', 'POSITION_AVG_PRICE', 'STREAK', 'SYMBOL', 'TRADES'),
    keyword_operator_word: (_) => words('ABOVE', 'AND', 'BELOW', 'BETWEEN', 'CROSSES', 'IS', 'NOT', 'NULL', 'OR'),
    keyword_aggregate: (_) => words('MAX', 'MEAN', 'MIN', 'OPEN', 'SUM'),
    keyword_literal: (_) => words('FALSE', 'TRUE'),
    call: ($) => prec(1, seq(field('name', $.identifier), '(')),
    member: ($) => prec(1, seq('.', field('name', $.identifier))),
    broker_symbol: (_) => /[A-Za-z_][A-Za-z0-9_]*:[A-Za-z0-9_][A-Za-z0-9_.\-]*/,
    duration: (_) => /\d+[smhd]/,
    number: (_) => /\d+(\.\d+)?([eE][+-]?\d+)?/,
    string: (_) => choice(/"([^"\\\n]|\\.)*"/, /'([^'\\\n]|\\.)*'/),
    comment: (_) => token(choice(seq('--', /.*/), seq('#', /.*/), seq('/*', /[^*]*\*+([^/*][^*]*\*+)*/, '/'))),
    operator: (_) => choice('->', '==', '<>', '!=', '<=', '>=', '<', '>', '=', '+', '-', '*', '/', '%'),
    punctuation: (_) => choice('(', ')', '[', ']', '{', '}', ',', ':', ';', '.', '@', '$'),
    identifier: (_) => /[A-Za-z_][A-Za-z0-9_]*/,
  },
});
